      </div>
      {days.map((d) => {
        const items = mo.items.filter((e) => e.date === d)
        return (
          <Section key={d} title={new Date(d + "T12:00").toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long" })}>
            {items.map((e) => (
              <Row key={e.id} className="gap-0 p-0 pr-1">
